<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Encomendas';$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$sql='SELECT e.*,c.nome cliente,u.nome usuario_nome FROM encomendas e JOIN clientes c ON c.id=e.cliente_id LEFT JOIN usuarios u ON u.id=e.usuario_id WHERE (e.numero LIKE ? OR c.nome LIKE ?)';$args=["%$q%","%$q%"];if($status!==''){$sql.=' AND e.status=?';$args[]=$status;}$sql.=' ORDER BY e.id DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$statuses=['Aberta','Aguardando','Confirmada','Em preparação','Pronta','Entregue','Cancelada'];include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Encomendas</h1><a class="btn primary" href="form.php">＋ Nova encomenda</a></div><div class="card"><form class="search-row"><input name="q" value="<?=e($q)?>" placeholder="Número ou cliente"><select name="status"><option value="">Todos os status</option><?php foreach($statuses as $s): ?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn secondary">Filtrar</button></form></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Número</th><th>Cliente</th><th>Data</th><th>Origem</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=e($r['cliente'])?></td><td><?=datetime_br($r['data_hora'])?></td><td><?=e($r['origem'])?></td><td><?=money($r['total'])?></td><td><?=status_badge($r['status'])?></td><td><a class="btn small secondary" href="detalhes.php?id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="7" class="empty">Nenhuma encomenda encontrada.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
